27	const quotePremium = (step: QuoteStep): number => {
28	  const policyBasePremium = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
29	  return policyBasePremium + policyBasePremium * FIRST_INSURANCE_SURCHARGE + PROCESSING_FEE;
30	};
