const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const surchargedPremium = policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE);
  return surchargedPremium + PROCESSING_FEE;
};
